        $apc=$this->apcDatabase();$this->seedEvent($apc);$apc->exec("INSERT INTO apc_envios(id,evento_id,bimestre_id,professor_usuario_id,professor_nome_snapshot,etapa,ano_serie,turma_id_externo,nome_original,nome_armazenado,mime_type,tamanho_bytes,sha256,caminho_relativo,atrasado,dias_atraso,enviado_em)VALUES(1,1,3,3,'Professor Um','EF_AF','EF7',10,'arquivo-professor.pdf','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.pdf','application/pdf',1200,'".str_repeat('a',64)."','envios/2026/08/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.pdf',0,0,'2026-08-11 10:00:00');INSERT INTO apc_envio_turmas(envio_id,turma_id_externo,turma_nome_snapshot)VALUES(1,10,'7º A')");
        $repository=new SubmissionRepository($apc);$access=new AccessRepository($main);$controller=new SubmissionController(new SubmissionService($repository,new EventRepository($apc),new TermRepository($apc),$access,new AuditRepository($apc),sys_get_temp_dir(),1048576,null,null,'2026-08-11'),$repository,$access,new View(dirname(__DIR__).'/apps/apc/resources/views'));$_SESSION['user']=['id'=>2,'nome'=>'Coordenação','perfil'=>'COORDENADOR'];$_SERVER['REQUEST_URI']='/apc';$response=$controller->index(new Request('GET','/apc',[],[],[]));
        self::assertStringContainsString('Professor e coordenação',$response->body);self::assertStringContainsString('Minhas APCs e APCs da escola',$response->body);self::assertStringContainsString('data-apc-view-tab="mine"',$response->body);self::assertStringContainsString('data-apc-view-panel="mine"',$response->body);self::assertStringContainsString('data-apc-submission',$response->body);self::assertStringContainsString('9º A',$response->body);self::assertStringContainsString('data-apc-view-panel="tracking"',$response->body);self::assertStringContainsString('<strong>Coordenação</strong>',$response->body);self::assertStringContainsString('data-apc-view-panel="files"',$response->body);self::assertStringContainsString('arquivo-professor.pdf',$response->body);self::assertStringContainsString('/apc/envios/1/excluir',$response->body);
    }
